'use strict';

let Primitive_option = require("@rescript/runtime/lib/js/Primitive_option.js");
let Webapi__Dom__Node = require("./Webapi__Dom__Node.js");
let Webapi__Dom__Slotable = require("./Webapi__Dom__Slotable.js");
let Webapi__Dom__ChildNode = require("./Webapi__Dom__ChildNode.js");
let Webapi__Dom__EventTarget = require("./Webapi__Dom__EventTarget.js");
let Webapi__Dom__CharacterData = require("./Webapi__Dom__CharacterData.js");
let Webapi__Dom__NonDocumentTypeChildNode = require("./Webapi__Dom__NonDocumentTypeChildNode.js");

function ofNode(node) {
  if (Webapi__Dom__Node.nodeType(node) === "Text") {
    return Primitive_option.some(node);
  }
}

function Impl(T) {
  return {
    ofNode: ofNode
  };
}

let include = Webapi__Dom__Node.Impl({});

Webapi__Dom__EventTarget.Impl({});

Webapi__Dom__CharacterData.Impl({});

Webapi__Dom__NonDocumentTypeChildNode.Impl({});

Webapi__Dom__ChildNode.Impl({});

Webapi__Dom__Slotable.Impl({});

let nodeType = include.nodeType;

exports.Impl = Impl;
exports.nodeType = nodeType;
exports.ofNode = ofNode;
/* include Not a pure module */
